import{_ as r,C as l,o as a,c as n,a2 as o,b as s,w as i,a as c,E as d,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const _=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-VIII/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-VIII/Lectura_Catedra_Evaluacion_1.md"}'),m={name:"materias/Proyecto_Sociotecnologico_III/documentacion/III-VIII/Lectura_Catedra_Evaluacion_1.md"};function p(I,e,g,f,b,A){const t=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-viii" tabindex="-1">Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre VIII) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-viii" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre VIII)&quot;">​</a></h2><h3 id="eje-tematico-metodologias-de-desarrollo-para-sistemas-de-informacion-institucionales" tabindex="-1">Eje Temático: Metodologías de Desarrollo para Sistemas de Información Institucionales <a class="header-anchor" href="#eje-tematico-metodologias-de-desarrollo-para-sistemas-de-informacion-institucionales" aria-label="Permalink to &quot;Eje Temático: Metodologías de Desarrollo para Sistemas de Información Institucionales&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-seleccion-metodologica-en-sistemas-complejos" tabindex="-1">🧭 Introducción: La Selección Metodológica en Sistemas Complejos <a class="header-anchor" href="#🧭-introduccion-la-seleccion-metodologica-en-sistemas-complejos" aria-label="Permalink to &quot;🧭 Introducción: La Selección Metodológica en Sistemas Complejos&quot;">​</a></h2><p>A medida que los sistemas informáticos crecen en envergadura — involucrando múltiples departamentos, usuarios con distintos privilegios de acceso y reglas de negocio complejas —, la elección de la metodología de desarrollo se convierte en una decisión crítica de arquitectura y gestión.</p><p>En el <strong>Trimestre VIII de PST III</strong>, el equipo debe aplicar una metodología que equilibre dos necesidades aparentemente contradictorias:</p><ol><li><strong>Rigor y Estabilidad Arquitectónica:</strong> Necesaria para garantizar la seguridad, integridad y consistencia de la base de datos institucional.</li><li><strong>Flexibilidad y Adaptabilidad Comunitaria:</strong> Necesaria para incorporar retroalimentación continua de los operadores sin descarrilar el cronograma.</li></ol><hr><h2 id="🏛️-capitulo-i-analisis-comparativo-de-metodologias-en-pst-iii" tabindex="-1">🏛️ CAPÍTULO I: Análisis Comparativo de Metodologías en PST III <a class="header-anchor" href="#🏛️-capitulo-i-analisis-comparativo-de-metodologias-en-pst-iii" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Análisis Comparativo de Metodologías en PST III&quot;">​</a></h2>',10)),(a(),s(u,null,{default:i(()=>[d(t,{id:"mermaid-35",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20M%5B%22%E2%9A%99%EF%B8%8F%20Metodolog%C3%ADas%20Aplicadas%20en%20PST%20III%22%5D%0A%20%20%20%20M%20--%3E%20R%5B%22%F0%9F%8F%9B%EF%B8%8F%20RUP%20%2F%20OpenUP%3A%20Enfoque%20dirigido%20por%20arquitectura%20y%20casos%20de%20uso%22%5D%0A%20%20%20%20M%20--%3E%20S%5B%22%E2%9A%A1%20Scrum%3A%20Gesti%C3%B3n%20%C3%A1gil%20por%20Sprints%20con%20entregas%20quincenales%22%5D%0A%20%20%20%20M%20--%3E%20ME%5B%22%F0%9F%87%BB%F0%9F%87%AA%20MERINDE%3A%20Metodolog%C3%ADa%20soberana%20venezolana%20de%20Software%20Libre%22%5D%0A%20%20%20%20M%20--%3E%20W%5B%22%F0%9F%8C%90%20WATCH%3A%20Desarrollo%20%C3%A1gil%20de%20soluciones%20web%20institucionales%22%5D%0A%0A%20%20%20%20style%20M%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20R%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A%20%20%20%20style%20S%20fill%3A%23064e3b%2Cstroke%3A%2310b981%2Ccolor%3A%23fff%0A%20%20%20%20style%20ME%20fill%3A%237c2d12%2Cstroke%3A%23ea580c%2Ccolor%3A%23fff%0A%20%20%20%20style%20W%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="_1-1-rup-y-openup-rational-open-unified-process" tabindex="-1">1.1 RUP y OpenUP (Rational / Open Unified Process) <a class="header-anchor" href="#_1-1-rup-y-openup-rational-open-unified-process" aria-label="Permalink to &quot;1.1 RUP y OpenUP (Rational / Open Unified Process)&quot;">​</a></h3><ul><li><strong>Orientación:</strong> Dirigido por Casos de Uso, centrado en la arquitectura, iterativo e incremental.</li><li><strong>Fase de Elaboración:</strong> Es la clave de este enfoque. Permite construir una &quot;línea base arquitectónica&quot; ejecutable que mitiga los mayores riesgos técnicos antes de pasar a la construcción masiva.</li><li><em>Idoneidad:</em> Excelente para sistemas administrativos o contables con reglas formales estrictas que no cambian a menudo.</li></ul><h3 id="_1-2-scrum-y-scrumban" tabindex="-1">1.2 Scrum y Scrumban <a class="header-anchor" href="#_1-2-scrum-y-scrumban" aria-label="Permalink to &quot;1.2 Scrum y Scrumban&quot;">​</a></h3><ul><li><strong>Orientación:</strong> Iterativa y adaptativa. Divide el desarrollo en <em>Sprints</em> de 2 o 3 semanas.</li><li><strong>Artefactos Clave:</strong><ul><li><em>Product Backlog:</em> Lista priorizada de todas las historias de usuario y requerimientos.</li><li><em>Sprint Backlog:</em> Conjunto de tareas seleccionadas para el sprint activo.</li><li><em>Incremento:</em> Versión de software potencialmente desplegable al final de cada ciclo.</li></ul></li><li><em>Idoneidad:</em> Ideal para aplicaciones web o móviles donde la comunidad necesita ver avances tangibles rápidamente.</li></ul><h3 id="_1-3-merinde-metodologia-del-cnti" tabindex="-1">1.3 MERINDE (Metodología del CNTI) <a class="header-anchor" href="#_1-3-merinde-metodologia-del-cnti" aria-label="Permalink to &quot;1.3 MERINDE (Metodología del CNTI)&quot;">​</a></h3><p>En el contexto del PST III, la metodología MERINDE adquiere un valor formativo e institucional inestimable:</p><ul><li>Define pautas obligatorias para el uso de formatos abiertos (OASIS, W3C).</li><li>Exige que los repositorios de código estén bajo licencias libres aprobadas por la FSF (Free Software Foundation) o la OSI.</li><li>Promueve la soberanía tecnológica, eliminando la dependencia de proveedores tecnológicos extranjeros.</li></ul><hr><h2 id="🎯-capitulo-ii-como-justificar-la-metodologia-en-el-informe-de-pst-iii" tabindex="-1">🎯 CAPÍTULO II: Cómo Justificar la Metodología en el Informe de PST III <a class="header-anchor" href="#🎯-capitulo-ii-como-justificar-la-metodologia-en-el-informe-de-pst-iii" aria-label="Permalink to &quot;🎯 CAPÍTULO II: Cómo Justificar la Metodología en el Informe de PST III&quot;">​</a></h2><p>En el Capítulo Metodológico del informe de proyecto, el equipo debe estructurar la justificación bajo tres dimensiones:</p><ol><li><strong>Adecuación al Dominio del Problema:</strong> ¿Por qué esta metodología es ideal para automatizar los procesos de esta institución específica?</li><li><strong>Capacidad y Tamaño del Equipo:</strong> Justificar cómo los roles del equipo estudiantil (3 a 5 personas) se alinean con los roles del marco metodológico.</li><li><strong>Mapeo de Entregables:</strong> Tabla donde cada fase o sprint se asocia con los diagramas UML, módulos de código y fechas de revisión con el tutor.</li></ol><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-1" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 1 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-1" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 1&quot;">​</a></h2><p>Para la Evaluación 1 del Trimestre VIII:</p><ol><li><strong>Capítulo Metodológico Consolidado:</strong> Comparativa argumentada entre metodologías tradicionales, ágiles y libres.</li><li><strong>Plan de Sprints o Fases del Proyecto:</strong> Con asignación de tareas, estimación de tiempos y criterios de aceptación por cada módulo.</li></ol>',15))])}const C=r(m,[["render",p]]);export{_ as __pageData,C as default};
